import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Payment webhook testing — kiwa SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/payment-testing.md","filePath":"concepts/payment-testing.md"}'),d={name:"concepts/payment-testing.md"};function i(s,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="payment-webhook-testing-—-kiwa-ssot" tabindex="-1">Payment webhook testing — kiwa SSOT <a class="header-anchor" href="#payment-webhook-testing-—-kiwa-ssot" aria-label="Permalink to &quot;Payment webhook testing — kiwa SSOT&quot;">​</a></h1><h2 id="why-webhooks-are-hard-to-test" tabindex="-1">Why webhooks are hard to test <a class="header-anchor" href="#why-webhooks-are-hard-to-test" aria-label="Permalink to &quot;Why webhooks are hard to test&quot;">​</a></h2><p>Payment providers push webhooks asynchronously from their backend. A test that spins up the real provider hits three problems at once:</p><ul><li><strong>flaky</strong> — the delivery is not synchronous. Poll timing decides pass/fail.</li><li><strong>coupled</strong> — a test account has to exist. Sandbox mode differs per provider.</li><li><strong>verify chain</strong> — the signature is HMAC-SHA256 over <code>{ts}.{body}</code> for Stripe, <code>{ts}:{body}</code> for Paddle, raw body only for Lemon Squeezy. Tampering vs stale-timestamp vs malformed-body must be exercised separately.</li></ul><p><code>@kiwa/payment</code> addresses all three by moving the sign + verify path in-process.</p><h2 id="the-paymentadapter-contract" tabindex="-1">The <code>PaymentAdapter</code> contract <a class="header-anchor" href="#the-paymentadapter-contract" aria-label="Permalink to &quot;The `PaymentAdapter` contract&quot;">​</a></h2><p>Three ops. All three providers implement the same shape.</p><ul><li><code>signWebhook({ type, amountCents, currency?, customerId, timestamp? })</code> — build a canonical rawBody + HMAC-SHA256 signature. Returns <code>{ rawBody, signature, event }</code>.</li><li><code>verifyWebhook({ rawBody, signature, toleranceMs? })</code> — timing-safe verify. Returns one of 4 reasons: <code>ok</code> / <code>bad-signature</code> / <code>stale-timestamp</code> / <code>malformed-body</code>.</li><li><code>onWebhook(handler)</code> + <code>emit(event)</code> — synchronous handler dispatch for end-to-end webhook flows.</li></ul><p>The provider prefix (<code>@kiwa/payment/stripe</code> etc.) triggers the common 7-axis release gate — no AI-LLM axes apply.</p><h2 id="the-3-provider-differences-that-matter" tabindex="-1">The 3 provider differences that matter <a class="header-anchor" href="#the-3-provider-differences-that-matter" aria-label="Permalink to &quot;The 3 provider differences that matter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>provider</th><th>signature scheme</th><th>payload shape</th><th>secret prefix</th></tr></thead><tbody><tr><td>Stripe</td><td><code>Stripe-Signature: t=...,v1=...</code> over <code>{ts}.{body}</code></td><td><code>data.object.{id,amount,currency}</code></td><td><code>whsec_...</code></td></tr><tr><td>Paddle Billing</td><td><code>Paddle-Signature: ts=...;h1=...</code> over <code>{ts}:{body}</code></td><td><code>data.attributes.totals.total</code> (string cents)</td><td><code>pdl_ntfset_...</code></td></tr><tr><td>Lemon Squeezy</td><td><code>X-Signature: &lt;hmac&gt;</code> over raw body</td><td><code>meta.event_name</code> + <code>data.attributes.total</code></td><td><code>lswhs_...</code></td></tr></tbody></table><p>The <code>PaymentEngine</code> shared core normalises these differences behind the adapter shape so consumer test code reads identical <code>PaymentWebhookEvent</code> fields regardless of provider.</p><h2 id="the-4-fixture-builders" tabindex="-1">The 4 fixture builders <a class="header-anchor" href="#the-4-fixture-builders" aria-label="Permalink to &quot;The 4 fixture builders&quot;">​</a></h2><ul><li><code>checkoutCompleted(adapter, { amountCents, currency?, customerId })</code></li><li><code>subscriptionCreated(adapter, { amountCents, currency?, customerId })</code></li><li><code>paymentFailed(adapter, { amountCents, currency?, customerId })</code></li><li><code>refunded(adapter, { amountCents, currency?, customerId })</code> — flips <code>amountCents</code> sign for the accounting delta</li></ul><p>For provider-specific event types (<code>invoice.upcoming</code>, <code>transaction.canceled</code>, etc.) call <code>adapter.signWebhook({ type: &#39;...&#39;, ... })</code> directly.</p><h2 id="the-4-verify-failure-modes" tabindex="-1">The 4 verify failure modes <a class="header-anchor" href="#the-4-verify-failure-modes" aria-label="Permalink to &quot;The 4 verify failure modes&quot;">​</a></h2><p>The tests you should write for every payment integration.</p><ul><li><strong><code>ok</code></strong> — happy path. Sign, verify, dispatch.</li><li><strong><code>bad-signature</code></strong> — tamper the body. Verify must reject.</li><li><strong><code>stale-timestamp</code></strong> — replay attack. Body signed 10 minutes ago, verify with <code>toleranceMs: 60_000</code> must reject.</li><li><strong><code>malformed-body</code></strong> — arbitrary garbage. JSON parse fails or <code>timestamp</code> field missing. Verify must reject.</li></ul><p>All 4 must pass before the endpoint reaches production. <code>@kiwa/payment</code> exercises each in unit-test time (no real webhook, no polling).</p><h2 id="when-not-to-use-the-mock" tabindex="-1">When NOT to use the mock <a class="header-anchor" href="#when-not-to-use-the-mock" aria-label="Permalink to &quot;When NOT to use the mock&quot;">​</a></h2><ul><li>Testing the actual HTTP round-trip against the real provider&#39;s endpoints — use the real SDK against sandbox / test-mode instead. The mock exercises the sign/verify byte contract, not the network.</li><li>Load / stress testing — the mock is deterministic, does not simulate real backend latency variance. Use the real provider (sandbox mode) for perf testing.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/12-payment">Tutorial 12 — Payment webhook mock</a></li><li><a href="https://www.npmjs.com/package/@kiwa/payment" target="_blank" rel="noreferrer"><code>@kiwa/payment</code> on npm</a></li></ul>',23)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
